/* Generated by Payload, then edited on purpose (P1, panel spec §2 and §2a pt 11): panel fonts,
   panel styles and the viewport for the phone. When Payload regenerates this file, put back the
   lines marked "P1". */
import config from '@payload-config'
import '@payloadcms/next/css'
import type { ServerFunctionClient } from 'payload'
import { handleServerFunctions, RootLayout } from '@payloadcms/next/layouts'
import type { Viewport } from 'next'
import React from 'react'

import { PANEL_APP } from '../../admin/brand' // P1
import { cinzel, manrope } from '../(site)/fonts' // P1
import '../../styles/tokens.css' // P2: creature colours on the Pulpit (one source, spec §2)
import '../../admin/styles/panel-tokens.css' // P1
import '../../admin/styles/panel.css' // P1
import { importMap } from './admin/importMap.js'
import './custom.scss'

type Args = {
  children: React.ReactNode
}

// P1: Payload sets no viewport. `cover` lets env(safe-area-inset-*) keep the app bar and the
// tabs clear of the notch and the home bar; the theme colour paints the phone's status bar.
export const viewport: Viewport = { viewportFit: 'cover', themeColor: PANEL_APP.themeColor }

const serverFunction: ServerFunctionClient = async function (args) {
  'use server'
  return handleServerFunctions({
    ...args,
    config,
    importMap,
  })
}

const Layout = ({ children }: Args) => (
  <RootLayout
    config={config}
    importMap={importMap}
    serverFunction={serverFunction}
    htmlProps={{ className: `${manrope.variable} ${cinzel.variable}` }} // P1
  >
    {children}
  </RootLayout>
)

export default Layout
